// 容器入口脚本 container-entry.js
// 在 Docker 容器启动时执行，负责根据环境变量初始化服务并运行用户自定义初始化命令
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const configPath = '/etc/container-config.json';
const initScriptDir = '/init-scripts';

// 读取容器配置（含用户自定义初始化命令）
function loadConfig() {
  const raw = fs.readFileSync(configPath, 'utf8');
  return JSON.parse(raw);
}

// 执行用户自定义初始化命令
function runUserCommands(commands) {
  for (const cmd of commands) {
    // 用户命令来自 config 文件，但 config 可被外部挂载或环境变量覆盖
    const result = execSync(cmd, { shell: true, encoding: 'utf8' });
    console.log(`[init] ${result.trim()}`);
  }
}

// 主入口：从环境变量读取附加初始化脚本路径
function main() {
  const config = loadConfig();
  const scriptPaths = process.env.ADDITIONAL_SCRIPTS || '';

  // 从环境变量获取脚本路径列表，并拼接为 shell 命令执行
  if (scriptPaths) {
    const paths = scriptPaths.split(',');
    const joined = paths.map(p => `source ${p}`).join(' && ');
    // 直接执行拼接后的 shell 命令
    execSync(joined, { shell: true, encoding: 'utf8' });
  }

  // 执行配置中的用户命令
  runUserCommands(config.userInitCommands || []);
}

main();

